ones = [0, 1, 11, 111, 1111, 11111, 111111, 1111111, 11111111, 111111111, 1111111111,
        11111111111, 111111111111, 1111111111111, 11111111111111, 111111111111111, 1111111111111111]

def getNumOfDigits(n):
    return int(math.floor(math.log10(n))) + 1

def decompose(n):
    if n <= 6:
        return n
    numOfDigits = getNumOfDigits(n)
    lower = ones[numOfDigits]
    if n < lower:
        upper = ones[numOfDigits - 1]
    elif n > lower:
        upper = ones[numOfDigits + 1]
    else:
        return numOfDigits
    resLower = decompose(n % lower) + (n // lower) * getNumOfDigits(lower)
    resUpper = float('inf')
    if upper - n < n:
        resUpper = decompose(upper - n) + getNumOfDigits(upper)
    return min(resLower, resUpper)

def main():
    # Initialize is not necessary in Python
